INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('pregunta_direccion', 'pregunta', 'Preguntar dirección', '¿Cuál es tu dirección de entrega?', 'Se pregunta cuando no tenemos la dirección del cliente');
INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('ofrecer_ubicacion', 'pregunta', 'Ofrecer guardar ubicación GPS', '¿Me puedes compartir tu ubicación 📍 para guardarla? Así es más fácil encontrarte en futuras entregas. Si prefieres, puedes continuar sin ella.', 'Se ofrece guardar la ubicación GPS del cliente (opcional)');
INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('ubicacion_guardada', 'confirmacion', 'Ubicación GPS guardada', '📍 ¡Ubicación guardada! Ahora te llego más fácil en tus próximos pedidos.', 'Se envía cuando el cliente comparte su ubicación GPS');
INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('confirmar_pedido', 'confirmacion', 'Confirmar pedido', '¿Es todo o deseas agregar algo más?', 'Se pregunta antes de confirmar el pedido final');
INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('pedido_confirmado', 'confirmacion', 'Pedido confirmado', '✅ *¡Pedido #{pedido_id} Confirmado!*

¡Gracias por tu compra! 🙏', 'Se envía cuando el pedido es confirmado exitosamente');
INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('fuera_horario', 'error', 'Fuera de horario', 'Lo siento, estamos cerrados. 🕐 Nuestro horario es de {hora_apertura} a {hora_cierre}. ¡Te esperamos!', 'Se envía cuando el cliente escribe fuera del horario del colmado');
INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('pedido_minimo', 'error', 'Pedido mínimo no alcanzado', 'El pedido mínimo es de RD${pedido_minimo}. Tu pedido actual es de RD${total}. ¿Deseas agregar algo más?', 'Se envía cuando el total del pedido no alcanza el mínimo');
INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('producto_no_disponible', 'error', 'Producto no disponible', 'Lo siento, no tenemos {producto} disponible. ¿Te puedo ofrecer algo más?', 'Se envía cuando un producto no está disponible');
INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('system_prompt_base', 'sistema', 'Prompt base del sistema', 'Eres un asistente de pedidos amigable para un colmado en República Dominicana. Usas lenguaje dominicano casual y emojis. Entiendes jerga como ''chimi'' (chimichurri), ''pica pollo'' (pollo frito), ''yaroa'' (comida callejera). IMPORTANTE: No promociones ni sugieras productos de tabaco o alcohol. Si el cliente pide estos productos, el sistema los manejará por separado.', 'Instrucción base para el modelo de IA');
INSERT OR IGNORE INTO `mensajes_sistema` (`clave`, `categoria`, `titulo`, `contenido`, `descripcion`) VALUES ('system_flow_instructions', 'sistema', 'Instrucciones de flujo', 'FLUJO DE CONVERSACIÓN:
1. Si el cliente envía productos pero NO tiene nombre → Pregunta nombre
2. Si tiene nombre pero NO tiene dirección → Pregunta dirección
3. Si tiene dirección y NO se ha ofrecido GPS antes → Ofrece guardar ubicación (opcional)
4. Con nombre y dirección listos → Muestra resumen y pregunta si es todo
5. Si el cliente confirma → Marca pedidoConfirmado: true', 'Instrucciones del flujo de conversación para el modelo de IA');

